    22→
    23→namespace Nethermind.Evm.TransactionProcessing
    24→{
    25→    public sealed class TransactionProcessor(
    26→        ISpecProvider? specProvider,
    27→        IWorldState? worldState,
    28→        IVirtualMachine? virtualMachine,
    29→        ICodeInfoRepository? codeInfoRepository,
    30→        ILogManager? logManager)
    31→        : TransactionProcessorBase(specProvider, worldState, virtualMachine, codeInfoRepository, logManager);
    32→
    33→    public abstract class TransactionProcessorBase : ITransactionProcessor
    34→    {
    35→        protected EthereumEcdsa Ecdsa { get; }
    36→        protected ILogger Logger { get; }
    37→        protected ISpecProvider SpecProvider { get; }
    38→        protected IWorldState WorldState { get; }
    39→        protected IVirtualMachine VirtualMachine { get; }
    40→        private readonly ICodeInfoRepository _codeInfoRepository;
    41→        private SystemTransactionProcessor? _systemTransactionProcessor;
    42→        private readonly ILogManager _logManager;
    43→
    44→        [Flags]
    45→        protected enum ExecutionOptions
    46→        {
    47→            /// <summary>
    48→            /// Just accumulate the state
    49→            /// </summary>
    50→            None = 0,
    51→
    52→            /// <summary>
    53→            /// Commit the state after execution
    54→            /// </summary>
    55→            Commit = 1,
    56→
    57→            /// <summary>
    58→            /// Restore state after execution
    59→            /// </summary>
    60→            Restore = 2,
    61→
    62→            /// <summary>
    63→            /// Skip potential fail checks
    64→            /// </summary>
    65→            SkipValidation = 4,
    66→
    67→            /// <summary>
    68→            /// Skip potential fail checks and commit state after execution
    69→            /// </summary>
    70→            SkipValidationAndCommit = Commit | SkipValidation,
    71→
    72→            /// <summary>
    73→            /// Commit and later restore state also skip validation, use for CallAndRestore
    74→            /// </summary>
    75→            CommitAndRestore = Commit | Restore | SkipValidation
    76→        }
    77→
    78→        protected TransactionProcessorBase(
    79→            ISpecProvider? specProvider,
    80→            IWorldState? worldState,
    81→            IVirtualMachine? virtualMachine,
    82→            ICodeInfoRepository? codeInfoRepository,
    83→            ILogManager? logManager)
    84→        {
    85→            ArgumentNullException.ThrowIfNull(logManager, nameof(logManager));
    86→            ArgumentNullException.ThrowIfNull(specProvider, nameof(specProvider));
    87→            ArgumentNullException.ThrowIfNull(worldState, nameof(worldState));
    88→            ArgumentNullException.ThrowIfNull(virtualMachine, nameof(virtualMachine));
    89→            ArgumentNullException.ThrowIfNull(codeInfoRepository, nameof(codeInfoRepository));
    90→
    91→            Logger = logManager.GetClassLogger();
    92→            SpecProvider = specProvider;
    93→            WorldState = worldState;
    94→            VirtualMachine = virtualMachine;
    95→            _codeInfoRepository = codeInfoRepository;
    96→
    97→            Ecdsa = new EthereumEcdsa(specProvider.ChainId);
    98→            _logManager = logManager;
    99→        }
   100→
   101→        public void SetBlockExecutionContext(in BlockExecutionContext blockExecutionContext)
   102→            => VirtualMachine.SetBlockExecutionContext(in blockExecutionContext);
   103→
   104→        public void SetBlockExecutionContext(BlockHeader header)
   105→        {
   106→            IReleaseSpec spec = SpecProvider.GetSpec(header);
   107→            BlockExecutionContext blockExecutionContext = new(header, spec);
   108→            SetBlockExecutionContext(in blockExecutionContext);
   109→        }
   110→
   111→        public TransactionResult CallAndRestore(Transaction transaction, ITxTracer txTracer) =>
   112→            ExecuteCore(transaction, txTracer, ExecutionOptions.CommitAndRestore);
   113→
   114→        public TransactionResult BuildUp(Transaction transaction, ITxTracer txTracer)
   115→        {
   116→            // we need to treat the result of previous transaction as the original value of next transaction
   117→            // when we do not commit
   118→            WorldState.TakeSnapshot(true);
   119→            return ExecuteCore(transaction, txTracer, ExecutionOptions.None);
   120→        }
   121→
   122→        public TransactionResult Execute(Transaction transaction, ITxTracer txTracer) =>
   123→            ExecuteCore(transaction, txTracer, ExecutionOptions.Commit);
   124→
   125→        public TransactionResult Trace(Transaction transaction, ITxTracer txTracer) =>
   126→            ExecuteCore(transaction, txTracer, ExecutionOptions.SkipValidationAndCommit);
   127→
   128→        public virtual TransactionResult Warmup(Transaction transaction, ITxTracer txTracer) =>
   129→            ExecuteCore(transaction, txTracer, ExecutionOptions.SkipValidation);
   130→
   131→        private TransactionResult ExecuteCore(Transaction tx, ITxTracer tracer, ExecutionOptions opts)
   132→        {
   133→            if (Logger.IsTrace) Logger.Trace($"Executing tx {tx.Hash}");
   134→            if (tx.IsSystem() || opts == ExecutionOptions.SkipValidation)
   135→            {
   136→                _systemTransactionProcessor ??= new SystemTransactionProcessor(SpecProvider, WorldState, VirtualMachine, _codeInfoRepository, _logManager);
   137→                return _systemTransactionProcessor.Execute(tx, tracer, opts);
   138→            }
   139→
   140→            TransactionResult result = Execute(tx, tracer, opts);
   141→            if (Logger.IsTrace) Logger.Trace($"Tx {tx.Hash} was executed, {result}");
   142→            return result;
   143→        }
   144→
   145→        protected virtual TransactionResult Execute(Transaction tx, ITxTracer tracer, ExecutionOptions opts)
   146→        {
   147→            BlockHeader header = VirtualMachine.BlockExecutionContext.Header;
   148→            IReleaseSpec spec = GetSpec(header);
   149→
   150→            // restore is CallAndRestore - previous call, we will restore state after the execution
   151→            bool restore = opts.HasFlag(ExecutionOptions.Restore);
   152→            // commit - is for standard execute, we will commit thee state after execution
   153→            // !commit - is for build up during block production, we won't commit state after each transaction to support rollbacks
   154→            // we commit only after all block is constructed
   155→            bool commit = opts.HasFlag(ExecutionOptions.Commit) || (!opts.HasFlag(ExecutionOptions.SkipValidation) && !spec.IsEip658Enabled);
   156→
   157→            TransactionResult result;
   158→            IntrinsicGas intrinsicGas = CalculateIntrinsicGas(tx, spec);
   159→            if (!(result = ValidateStatic(tx, header, spec, opts, in intrinsicGas))) return result;
   160→
   161→            UInt256 effectiveGasPrice = CalculateEffectiveGasPrice(tx, spec.IsEip1559Enabled, header.BaseFeePerGas);
   162→
   163→            VirtualMachine.SetTxExecutionContext(new(tx.SenderAddress, _codeInfoRepository, tx.BlobVersionedHashes, in effectiveGasPrice));
   164→
   165→            UpdateMetrics(opts, effectiveGasPrice);
   166→
   167→            bool deleteCallerAccount = RecoverSenderIfNeeded(tx, spec, opts, effectiveGasPrice);
   168→
   169→            if (!(result = ValidateSender(tx, header, spec, tracer, opts))) return result;
   170→            if (!(result = BuyGas(tx, spec, tracer, opts, effectiveGasPrice, out UInt256 premiumPerGas, out UInt256 senderReservedGasPayment, out UInt256 blobBaseFee))) return result;
   171→            if (!(result = IncrementNonce(tx, header, spec, tracer, opts))) return result;
   172→
   173→            if (commit) WorldState.Commit(spec, tracer.IsTracingState ? tracer : NullTxTracer.Instance, commitRoots: false);
   174→
   175→            // substate.Logs contains a reference to accessTracker.Logs so we can't Dispose until end of the method
   176→            using StackAccessTracker accessTracker = new();
   177→
   178→            int delegationRefunds = (!spec.IsEip7702Enabled || !tx.HasAuthorizationList) ? 0 : ProcessDelegations(tx, spec, accessTracker);
   179→
   180→            long gasAvailable = tx.GasLimit - intrinsicGas.Standard;
   181→            if (!(result = BuildExecutionEnvironment(tx, spec, _codeInfoRepository, accessTracker, out ExecutionEnvironment env))) return result;
   182→
   183→            int statusCode = !tracer.IsTracingInstructions ?
   184→                ExecuteEvmCall<OffFlag>(tx, header, spec, tracer, opts, delegationRefunds, intrinsicGas, accessTracker, gasAvailable, env, out TransactionSubstate substate, out GasConsumed spentGas) :
   185→                ExecuteEvmCall<OnFlag>(tx, header, spec, tracer, opts, delegationRefunds, intrinsicGas, accessTracker, gasAvailable, env, out substate, out spentGas);
   186→
   187→            PayFees(tx, header, spec, tracer, in substate, spentGas.SpentGas, premiumPerGas, blobBaseFee, statusCode);
   188→            tx.SpentGas = spentGas.SpentGas;
   189→
   190→            // Finalize
   191→            if (restore)
   192→            {
   193→                WorldState.Reset(resetBlockChanges: false);
   194→                if (deleteCallerAccount)
   195→                {
   196→                    WorldState.DeleteAccount(tx.SenderAddress!);
   197→                }
